; =============================================================================
; BANK $79 — STORY HOOKS: the Milly hook (S121, ROADMAP P3.16 + E7), the
; new game's start (S152, ROADMAP E3 a2), the title screen, the credits and the
; original game's story at a point (S153, ROADMAP E5), the memorial (S154), the
; breeding hints — monuments and archives (S158, ROADMAP E15)
; Engine template (sha256-pinned, PROJECT_COMPILER §5). The data after the
; head is generated by editor2/core/milly.py (`hooks79`) from
; custom.milly_hook + custom.new_game (editor2/core/newgame.py) + custom.title /
; custom.credits / the story-point and roll-the-credits steps (editor2/core/
; ending.py); with all of them OFF the whole bank stays the vanilla zeros (this
; head is not emitted at all).
;
; THE PLAYER'S LOOK (MONSTER_DATA "The player's sprite (S121)"): every draw of
; the player shape — sprite type $FFC7 = 0: the field player (bank $01, HRAM
; $FF8A = 0), the naming screen's hero icon (bank $09) — goes through bank $04
; entry 2 / 3 (type < $10: palette data_4157 = $02, frame tables data_4137 ->
; $04:$7237 = Terry). Once event flag MILLY_FLAG ($179F, extended, saved,
; zeroed by a new game) is set, type 0 is drawn with the NPC sprite's own six
; frames and palette instead; the sheet is loaded by entry 1 (field) or by the
; naming screen's table (patches/bank_009.asm region milly_naming_icon).
; The flag is set by the bedroom's east-room scene when Milayou is dragged
; into the dresser (patches/bank_00e.asm region milly_bedroom_script).
;   entry 0  MillyShapeTable  — bank $04 entry 2 / 3 (regions milly_shape_04a /
;            milly_shape_04b: `call HramScr_4126 / ld de, data_4137` ->
;            `ld hl, $7900 / rst $10`, same size): ORs the palette into
;            $FFCA and returns DE = the frame-table root.
;   entry 1  MillyPlayerSheet — bank $01 LoadFieldTilesDMA (region
;            milly_player_sheet, same size): the field sheet -> VRAM $8000,
;            and (flag set) the frame tables -> WRAM wMillyLayout.
; The frame tables live in WRAM because the metasprite builders ($0D91, bank
; $04 SaveScr_40cd) read them with bank $04 mapped; bank $04 has no room.
; Flag clear: both do exactly what the replaced code did (Terry).
; =============================================================================

SECTION "ROM Bank $079", ROMX[$4000], BANK[$79]

    db $79                          ; bank self-id (rst $10 restores by it)
    dw MillyShapeTable              ; entry 0
    dw MillyPlayerSheet             ; entry 1
    dw NewGameStart                 ; entry 2 (S152)
    dw TitleText                    ; entry 3 (S153) the title screen's own lines
    dw CreditsAfter                 ; entry 4 (S153) where the field goes after the credits
    dw StoryPointApply              ; entry 5 (S153) the original game's story at a point
    dw MemBattleStart               ; entry 6 (S154) the memorial: the party count as a battle starts
    dw MemBattleEnd                 ; entry 7 (S154) the memorial: a won boss / arena class / Starry Night
    dw MemRoomTiles                 ; entry 8 (S154) the memorial: the room's statues (roll + draw)
    dw MemSay                       ; entry 9 (S154) the memorial: a statue's words (story command 7)
    dw HintCommand                  ; entry 10 (S158) breeding hints: monuments / archives (story command 8)
    dw HintBreed                    ; entry 11 (S158) breeding hints: an egg bred by a hint's cross (bank $16)
    dw HintSay                      ; entry 12 (S158) breeding hints: the riddle swapped in (bank $60 TextOverride)

MILLY_FLAG EQU $179F                ; extended flag: the player is Milly
MILLY_FLAG_MASK EQU $80 >> (MILLY_FLAG & 7)   ; FlagAddr's bit order (bank $73 entry 21)

; Entry 0. In: $FFC7 = sprite type (< $10), $FFC8 frame, $FFCA OAM attr (the
; facing flip). Out: $FFCA |= palette, DE = level-1 table for the caller's
; metasprite builder. Vanilla (HramScr_4126 + `ld de, data_4137`): palette
; data_4157[type] = $02 for all 16 types, DE = data_4137 ($04:$4137).
MillyShapeTable:
    ld a, [wExtFlags + (MILLY_FLAG - $1000) / 8]
    and MILLY_FLAG_MASK
    jr z, .vanilla
    ldh a, [$c7]
    or a
    jr nz, .vanilla                 ; not the player shape
    ld a, [wMillyLayout + 1]
    or a
    jr z, .vanilla                  ; tables not built yet (no room loaded since)
    ld hl, MillyPlayerAttr
    ldh a, [$ca]
    or [hl]
    ldh [$ca], a
    ld de, wMillyLayout
    ret
.vanilla:
    ldh a, [$ca]
    or $02                          ; data_4157[type]
    ldh [$ca], a
    ld de, $4137                    ; data_4137 (bank $04)
    ret

; Entry 1. The player's 2bpp sheet -> VRAM $8000: Terry's gfx-ID $2F00 (20
; tiles), or (flag set) the NPC sheet (16 tiles) + its frame tables -> WRAM.
MillyPlayerSheet:
    ld de, $2f00
    ld a, [wExtFlags + (MILLY_FLAG - $1000) / 8]
    and MILLY_FLAG_MASK
    jr z, .load
    ld hl, MillyLayoutImage
    ld de, wMillyLayout
    ld b, MillyLayoutImageEnd - MillyLayoutImage
.copy:
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, .copy
    ld hl, MillyPlayerGfx
    ld a, [hl+]
    ld e, a
    ld d, [hl]
.load:
    ld hl, $8000
    jp WaitDMATransfer

; Entry 2 (S152, ROADMAP E3 a2 — custom.new_game, editor2/core/newgame.py).
; Far-called by bank $15 TitleNewGameInit (region newgame_start: `ld hl, $7902 /
; rst $10` + 4 nop, same size) in place of `ld a, $2f / ld [wMapID], a /
; ld [wMapIDMirror], a` — right after the new game zeroed HRAM $FF8A-$FFAA and
; WRAM $C8EA-$D9E9 (bank $73 entry 7). NewGameData (generated):
;   db map id, db region + 1 (0 = region 0), db cell (0 = the map's default
;   spawn: bank $01 DefaultSpawnTable — the intro bedroom; 1 = the cell below)
;   dw X px, dw Y px          ; cell * 16 + 8, absolute in the room
;   dw flag … , $FFFF         ; EXTENDED flags ($1000+) ON at the start
; Only extended flags: the first field load of a new game ($C8EA = 0) runs bank
; $01 ClearAnimationState, which zeroes $D92A-$D9E9 again — the step counters
; and the game's own flags $0000-$0277 (measured S152). The opening's story
; flags are set by the start room's first scene instead (newgame.lower).
; The cell goes through the WARP MAILBOX: wIsPlayerChangingMaps = 1 makes the
; first load a warp arrival — the room from wWarpGateId (flag 0 = a room), bank
; $01 LoadFieldTilesDMA takes wWarpSpawn* instead of DefaultSpawnTable (which
; has no row for a custom room) and that load clears the flag (measured S152,
; PyBoy: one load, no second transition; wWarpGateId left 0 loads the Castle). The region goes through wWarpRegion
; (bank $73 RegionCommit at that room commit, as the Milly hook's whirl does).
NewGameStart:
    ld hl, NewGameData
    ld a, [hl+]
    ld [wMapID], a
    ld [wMapIDMirror], a
    ld a, [hl+]
    ld [wWarpRegion], a
    ld a, [hl+]
    or a
    jr z, .nocell
    ld a, $01
    ld [wIsPlayerChangingMaps], a
    ld a, [wMapID]
    ld [wWarpGateId], a             ; the mailbox's room (the load takes it from here)
    xor a
    ld [wWarpFlag], a               ; 0 = a room, not a gate
    ld de, wWarpSpawnXLo            ; X lo, X hi, Y lo, Y hi ($C96F-$C972)
    ld b, 4
.cell:
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, .cell
    jr .flags
.nocell:
    inc hl
    inc hl
    inc hl
    inc hl
.flags:
    ld a, [hl+]
    ld c, a
    ld a, [hl+]
    ld b, a
    and c
    inc a
    ret z                           ; $FFFF ends the flags
    push hl
    call SetEventFlag               ; BC = the flag (bank $73 FlagAddr: wExtFlags)
    pop hl
    jr .flags

; Entry 3 (S153, ROADMAP E5 — custom.title, editor2/core/ending.py). Far-called
; by bank $5F TitleInitDone (region title_text: `ld hl, $7903 / rst $10 / ret`, the
; same 5 bytes as `ld a, $00 / ldh [rVBK], a / ret`) at the end of TitleInit, with
; the LCD still off (the mode init turns it on). The title's own tiles fill VRAM
; bank 0; VRAM bank 1's tiles are unused there (measured S153), so the project's
; lines are drawn from bank 1: its tiles go to bank 1 $8800+ (tile ids $80+; the
; title's LCDC $83 = the $8800 tile block for ids $80-$FF) and every cell gets the
; tile id (bank 0) + attribute palette 5 | bank-1 bit ($0D, bank 1). DMG (wIsGBC 0):
; nothing (no VRAM bank 1). Ends with VRAM bank 0 selected (the replaced code's job).
; TitleTextData (generated): db the number of tiles, its tiles (16 B each), then
; per line: dw the BG map address, db n, n tile ids; dw $0000 ends.
TitleText:
    ld a, [wIsGBC]
    or a
    jr z, .done
    ld a, $01
    ldh [rVBK], a
    ld hl, TitleTextData
    ld a, [hl+]
    ld c, a                         ; C = tiles
    ld de, $8800
    or a
    jr z, .lines
.tile:
    ld b, 16
.byte:
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, .byte
    dec c
    jr nz, .tile
.lines:
    ld a, [hl+]
    ld e, a
    ld a, [hl+]
    ld d, a
    or e
    jr z, .done
    ld b, [hl]                      ; B = cells
    inc hl
.cell:
    xor a
    ldh [rVBK], a
    ld a, [hl+]
    ld [de], a                      ; bank 0: the tile id
    ld a, $01
    ldh [rVBK], a
    ld a, $0d
    ld [de], a                      ; bank 1: palette 5, the tile from VRAM bank 1
    inc de
    dec b
    jr nz, .cell
    jr .lines
.done:
    xor a
    ldh [rVBK], a
    ret

; Entry 4 (S153). Far-called by bank $5F CreditsDone (region credits_after: `ld hl,
; $7904 / rst $10 / jr CreditsDoneWarpEnd` + 32 nop, the same 38 bytes as the
; mailbox block) when the credits are over: the WARP MAILBOX to wCreditsAfter's
; place (set by the "Roll the credits" step's story command 6 just before the
; credits) — or, +0 = 0, the game's own intro bedroom ($2F, X $38, Y $C8) as the
; replaced code did. The region goes through wWarpRegion (bank $73 RegionCommit).
; Leaves wIsPlayerChangingMaps = 1 (the code after the region turns the field on).
CreditsAfter:
    ld hl, wCreditsAfter
    ld a, [hl]
    or a
    jr z, .bedroom
    xor a
    ld [hl+], a                     ; used once
    ld a, [hl+]
    ld [wWarpGateId], a
    ld a, [hl+]
    ld [wWarpRegion], a
    ld de, wWarpSpawnXLo            ; X lo, X hi, Y lo, Y hi
    ld b, 4
.spawn:
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, .spawn
    jr .go
.bedroom:
    ld a, $2f
    ld [wWarpGateId], a
    ld a, $38
    ld [wWarpSpawnXLo], a
    xor a
    ld [wWarpSpawnXHi], a
    ld [wWarpSpawnYHi], a
    ld a, $c8
    ld [wWarpSpawnYLo], a
.go:
    xor a
    ld [wWarpFlag], a               ; 0 = a room
    ld a, $01
    ld [wIsPlayerChangingMaps], a
    ret

; Entry 5 (S153). Bank $77 StoryCommand kind 5 story_point [n] far-calls it with
; E = n: the original game's saved story as at a story point (editor2/core/
; story_state.py: the game's own scripts run to that point, from the original
; opening's measured state — EVENT_FLAGS "Story state at a story point"). Record n
; of StoryPointPtrs (generated): rows `dw address / db keep, value` — the byte :=
; (byte AND keep) OR value — then dw $0000. The rows cover the game's event flags
; $0000-$017F / $0248-$0257 (keep = the project's own pool flags $0158-$0167 in
; those bytes), the room states $D92A-$D99A, the arena classes $CAB4 and the King's
; speech $D9E3; nothing else (the project's extended flags, the party, gold …).
StoryPointApply:
    ld a, e
    cp STORY_POINT_COUNT
    ret nc
    ld l, a
    ld h, $00
    add hl, hl
    ld de, StoryPointPtrs
    add hl, de
    ld a, [hl+]
    ld h, [hl]
    ld l, a
.row:
    ld a, [hl+]
    ld e, a
    ld a, [hl+]
    ld d, a
    or e
    ret z
    ld a, [de]
    and [hl]
    inc hl
    or [hl]
    inc hl
    ld [de], a
    jr .row

; =============================================================================
; S154 — THE MEMORIAL (editor2/core/memorial.py; PROJECT_COMPILER §2.62,
; DATA_STRUCTURES "The memorial (S154)"). Statues in the project's rooms show the
; monsters that won a boss battle, an arena class or Starry Night and have since
; LEFT the player (bred, released, traded): each statue = 4 of its room's own tile
; ids (the author's empty-statue picture), and at a room load the monster's standing
; picture is drawn over them (its pixels of colour 0 let the picture behind show).
;
; THE LIST — SRAM bank 3 from MEM_SRAM, a ring of MEM_RING entries of 8 bytes:
;   +0 tag, +1 species, +2 level (its latest win), +3..+6 its nickname (4), +7 0.
; Live entries = MIN(wMemCount, MEM_CAP) from ring index wMemHead (wMemCount and
; wMemHead ride the explicit save: bank $73 MemorialCommit / MemorialRestore); full
; = the oldest is dropped (MEM_RING = MEM_CAP + 9 keeps the saved window intact for
; nine new entries after a save). An entry is (tag, species): THE TAG is written into
; the monster's own record byte +$82 (resistance 26: the battle packer reads its low
; two bits, and breeding adds the two parents' bytes mod 8 — so a tag is a MULTIPLE OF
; 8: 8, 16 … 248; KEY_LESSONS S154). [S159] Resistance 26 is EARTH (ROADMAP E16): its
; level 0-3 shares the byte in bits 0-1 (bank $51 packs +$82 & 3 into position 27), so
; the tag = +$82 & $F8 everywhere here and a tag is written OR-ed over bits 0-2 (two
; parents' Earth levels sum to 6 at most: (p1 + p2) & 7 is still the levels' sum and
; never 7). A monster is "still with the
; player" while any record of the 40 slots (or the bank-2 sleep pool while it is
; active, $CA41 bit 7 + magic "P1") has that species and that tag.
;
; Generated (memorial.py data_lines): MEM_CAP / MEM_RING, MemPicBank (the picture
; bank: entry 0 MemPicDraw, 64 B per species), MemRoomTable (rows db region, map id,
; n, n x [4 tile ids TL TR BL BR, the shade map]; db $FF ends — S154 r2: the shade
; map = the palette index of the monster's colours 1 / 2 / 3, 2 bits each), MemBossEids
; (the bosses fought by a plain battle op: dw EID …, $FFFF).
; =============================================================================
MEM_SRAM EQU $a110                  ; SRAM bank 3: the ring
MEM_STATUES EQU 8                   ; statues a room can have (wMemPicks)

; Entry 6. Bank $50 BattlePhase00_PartyAliveCheck (region memorial_battle_start: `ld hl,
; $7906 / rst $10` in place of `ld hl, $1702 / rst $10`): the party count as the battle
; starts — a monster that JOINS in this battle is appended after them.
MemBattleStart:
    ld a, [$ca8d]
    ld [wMemPartyN], a
    ld hl, $1702                    ; the replaced call (bank $17 entry 2)
    rst $10
    ret

; Entry 7. Bank $50 BattleExitHandler (region memorial_battle_end: `ld hl, $7907 /
; rst $10` in place of `ld hl, $0106 / rst $10`), every battle's end with its state
; intact. A WIN ($DB55 = 0) of: an arena class (map $5D or the project's arena:
; $D999 = 0, class $D9CE < 8, its third match $D9CD = 3), Starry Night's final ($D999
; = 2), a boss battle ($DA09 = 3: every gate boss op $5A / $5B and every project
; conversation battle) or a listed boss fought by a plain battle op ($DA09 = 1 and
; the first enemy's EID $DA03 in MemBossEids). The fighters = the first MIN(the count
; at the start, $CA8D) of the party list (fainted ones too) -> MemUpsert each.
MemBattleEnd:
    ld hl, $0106                    ; the replaced call (bank $01 entry 6)
    rst $10
    ld a, [wBattlePostFlag]
    or a
    ret nz                          ; lost / fled / undecided
    ld a, [wMemPartyN]
    or a
    ret z
    call ArenaMapID
    cp $5d
    jr nz, .notArena
    ld a, [$d999]
    cp $02
    jr z, .record                   ; Starry Night's final
    or a
    ret nz                          ; Starry's rounds / Monster Grandpa's match
    ld a, [$d9ce]
    cp $08
    ret nc
    ld a, [$d9cd]
    cp $03
    ret nz                          ; a class's first / second match
    jr .record
.notArena:
    ld a, [$da09]
    cp $03
    jr z, .record
    cp $01
    ret nz
    ld a, [$da03]
    ld c, a
    ld a, [$da04]
    ld b, a
    ld hl, MemBossEids
.eid:
    ld a, [hl+]
    ld e, a
    ld a, [hl+]
    ld d, a
    and e
    inc a
    ret z                           ; $FFFF: not a listed boss
    ld a, e
    cp c
    jr nz, .eid
    ld a, d
    cp b
    jr nz, .eid
.record:
    ld a, [$ca8d]
    ld b, a
    ld a, [wMemPartyN]
    cp b
    jr c, .n
    ld a, b
.n:
    or a
    ret z
    ld [wMemTmp + 1], a             ; the fighters
    ld c, 0
.member:
    push bc
    ld a, c
    ld hl, $ca8e
    add l
    ld l, a
    jr nc, .m
    inc h
.m:
    ld a, [hl]
    cp $ff
    call nz, MemUpsert
    pop bc
    inc c
    ld a, [wMemTmp + 1]
    cp c
    jr nz, .member
    ret

; A = a party slot -> the monster on the list: tagged already (its entry gets this
; win's level and its nickname; an entry dropped from the full list comes back at the
; end) or a new tag + a new entry. Eggs are left alone. [S159] the tag = +$82 & $F8
; (bits 0-1 = the monster's Earth level). Clobbers all.
MemUpsert:
    ld [wMemTmp], a
    ld hl, $cac1
    call GetMonsterDataPtr          ; HL = the record
    ld a, [hl]
    or a
    ret z                           ; empty
    push hl
    ld de, $63
    add hl, de
    ld a, [hl]
    pop hl
    or a
    ret nz                          ; an egg
    push hl
    ld de, $82
    add hl, de
    ld a, [hl]
    and $F8                         ; [S159] bits 0-1 = Earth, not the tag
    ld [wMemCur], a                 ; +0 the tag
    pop hl
    push hl
    ld de, $09
    add hl, de
    ld a, [hl]
    ld [wMemCur + 1], a             ; +1 the species
    pop hl
    push hl
    ld de, $4b
    add hl, de
    ld a, [hl]
    ld [wMemCur + 2], a             ; +2 the level
    pop hl
    inc hl                          ; +$01 the nickname
    ld de, wMemCur + 3
    ld b, 4
.nick:
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, .nick
    ld a, [wMemCur]
    ld b, a                         ; [S159] already & $F8: always a tag or 0
    or a
    jr z, .new
    ld d, b
    ld a, [wMemCur + 1]
    ld e, a
    call MemFind
    jr nc, .append                  ; dropped from a full list: back at the end
    call MemRing
    jp MemWrite                     ; this win's level + nickname
.new:
    call MemAlloc
    or a
    ret z                           ; 31 of this species tagged already
    ld [wMemCur], a
    ld b, a
    ld a, [wMemTmp]
    ld hl, $cac1 + $82
    call GetMonsterDataPtr
    ld a, [hl]
    and $07                         ; [S159] keep the Earth level (bits 0-1)
    or b
    ld [hl], a                      ; the record's +$82 := the tag | Earth
.append:
    ld a, [wMemCount]
    call MemRing                    ; (head + count) mod MEM_RING
    call MemWrite
    ld a, [wMemCount]
    cp MEM_CAP
    jr nc, .full
    inc a
    ld [wMemCount], a
    ret
.full:
    ld a, [wMemHead]                ; the oldest goes
    inc a
    cp MEM_RING
    jr c, .head
    xor a
.head:
    ld [wMemHead], a
    ret

; -> A = the first tag 8, 16 … 248 no monster of species [wMemCur + 1] carries (the
; 40 slots, the sleep pool, the list); 0 = none free.
MemAlloc:
    ld a, [wMemCur + 1]
    ld e, a
    ld d, 8
.try:
    push de
    call MemTagUsed
    pop de
    jr nc, .free
    ld a, d
    add 8
    ld d, a
    jr nz, .try
    xor a
    ret
.free:
    ld a, d
    ret

; D = tag, E = species -> carry = a live entry or a monster of the 40 slots / the
; active sleep pool has them. Keeps DE.
MemTagUsed:
    call MemFind
    ret c
    ld c, 0
.slot:
    ld a, c
    ld hl, $cac1
    call GetMonsterDataPtr
    call MemRecMatch
    ret c
    inc c
    ld a, c
    cp 40
    jr nz, .slot
    ld a, [$ca41]
    bit 7, a
    jr z, .no                       ; no sleeping monsters
    ld a, $02
    ld [$4100], a
    ld a, [$a000]
    cp $50
    jr nz, .poolNo
    ld a, [$a001]
    cp $31
    jr nz, .poolNo
    ld hl, $a010
    ld c, 40
.pool:
    call MemRecMatch
    jr c, .poolYes
    push de
    ld de, $95
    add hl, de
    pop de
    dec c
    jr nz, .pool
.poolNo:
    xor a
    ld [$4100], a
.no:
    and a
    ret
.poolYes:
    xor a
    ld [$4100], a
    scf
    ret

; HL = a record, D = tag, E = species -> carry = in use with that species and tag.
; Keeps BC, DE, HL.
MemRecMatch:
    ld a, [hl]
    or a
    ret z
    push hl
    push bc
    ld bc, $09
    add hl, bc
    ld a, [hl]
    cp e
    jr nz, .no
    ld bc, $82 - $09
    add hl, bc
    ld a, [hl]
    and $F8                         ; [S159] the tag (bits 0-1 = Earth)
    cp d
    jr nz, .no
    pop bc
    pop hl
    scf
    ret
.no:
    pop bc
    pop hl
    and a
    ret

; HL = a record -> carry + D = its tag, E = its species when it is in use and
; tagged (+$82 & $F8 not 0; [S159] bits 0-1 = the Earth level). Keeps BC, HL.
MemRecTag:
    ld a, [hl]
    or a
    ret z
    push hl
    push bc
    ld bc, $09
    add hl, bc
    ld e, [hl]
    ld bc, $82 - $09
    add hl, bc
    ld a, [hl]
    and $F8                         ; [S159] the tag (bits 0-1 = Earth)
    ld d, a
    pop bc
    pop hl
    or a
    ret z
    scf
    ret

; D = tag, E = species -> carry + A = the live index of their entry. Keeps DE.
MemFind:
    ld c, 0
.loop:
    ld a, [wMemCount]
    cp c
    jr z, .no
    ld a, c
    call MemRing
    call MemRingAddr
    call MemBank3
    ld a, [hl+]
    cp d
    jr nz, .next
    ld a, [hl]
    cp e
    jr nz, .next
    call MemBank0
    ld a, c
    scf
    ret
.next:
    call MemBank0
    inc c
    jr .loop
.no:
    and a
    ret

; A = live index -> A = its ring index (wMemHead + A) mod MEM_RING. Clobbers B.
MemRing:
    ld b, a
    ld a, [wMemHead]
    add b
    cp MEM_RING
    ret c
    sub MEM_RING
    ret

; A = ring index -> HL = its entry in SRAM bank 3.
MemRingAddr:
    ld l, a
    ld h, $00
    add hl, hl
    add hl, hl
    add hl, hl
    push de
    ld de, MEM_SRAM
    add hl, de
    pop de
    ret

; A = ring index: wMemCur's 7 bytes + 0 -> that entry. Clobbers B, DE, HL.
MemWrite:
    call MemRingAddr
    call MemBank3
    ld de, wMemCur
    ld b, 7
.w:
    ld a, [de]
    inc de
    ld [hl+], a
    dec b
    jr nz, .w
    xor a
    ld [hl], a
    jp MemBank0

MemBank3:
    push af
    ld a, $0a
    ld [$0100], a                   ; SRAM enabled (as CF3 keeps it)
    ld a, $03
    ld [$4100], a
    pop af
    ret

MemBank0:
    push af
    xor a
    ld [$4100], a
    pop af
    ret

; Entry 8. Bank $0B RoomEntry0_TilesetLoader / RoomEntry1_GraphicsLoader (regions
; memorial_tiles_0 / memorial_tiles_1: `ld hl, $7908 / rst $10` + 3 nop over the dead
; `ld a, [wMapID] / ld a, $08 / jr nz` right after the room sheet reached $9000) and
; bank $77 BreedClose (MemorialRedraw77, after its own sheet reload): a memorial room
; (MemRoomTable) rolls its statues when it is a different place than the last full
; load (so a battle, a menu or the breeding screens keep them), then draws every
; statue that shows a monster. Other rooms only note their place. Clobbers all.
; S158: every room load first notes its visit for the breeding hints (HintRoomNote:
; a different place / gate / floor = a new visit, the monuments pick again).
MemRoomTiles:
    call HintRoomNote
    call MemFindRoom
    jr c, .room
    ld a, [wMapRegion]
    ld [wMemPlace], a
    ld a, [wMapID]
    ld [wMemPlace + 1], a
    ret
.room:
    push hl
    push bc
    ld hl, wMemPlace
    ld a, [wMapRegion]
    cp [hl]
    jr nz, .new
    inc hl
    ld a, [wMapID]
    cp [hl]
    jr z, .same
.new:
    ld a, [wMapRegion]
    ld [wMemPlace], a
    ld a, [wMapID]
    ld [wMemPlace + 1], a
    pop bc
    push bc
    call MemRoll
.same:
    pop bc
    pop hl
    ld c, 0
.draw:
    ld a, c
    cp b
    ret z
    push bc
    push hl
    ld e, c
    ld d, $00
    ld hl, wMemPicks
    add hl, de
    ld a, [hl]
    cp $ff
    jr z, .next
    call MemRingAddr
    inc hl
    call MemBank3
    ld a, [hl]                      ; its species
    call MemBank0
    ld [wMemDraw], a
    pop hl
    push hl
    ld de, wMemDraw + 1
    ld b, 5                         ; the 4 tile ids + the shade map
.ids:
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, .ids
    ld a, [MemPicBank]
    ld h, a
    ld l, $00
    rst $10                         ; the picture bank's entry 0 MemPicDraw
.next:
    pop hl
    ld de, 5                        ; a statue's row: 4 tile ids + the shade map
    add hl, de
    pop bc
    inc c
    jr .draw

; -> carry + HL = the room's statue rows (4 tile ids + the shade map each), B = its
; statues when (wMapRegion, wMapID) has a MemRoomTable row.
MemFindRoom:
    ld hl, MemRoomTable
.row:
    ld a, [hl+]
    cp $ff
    jr z, .none
    ld b, a
    ld a, [hl+]
    ld c, a
    ld a, [hl+]
    ld e, a
    ld a, [wMapRegion]
    cp b
    jr nz, .skip
    ld a, [wMapID]
    cp c
    jr nz, .skip
    ld b, e
    scf
    ret
.skip:
    ld a, e
    add a
    add a
    add e                           ; 5 bytes a statue
    add l
    ld l, a
    jr nc, .row
    inc h
    jr .row
.none:
    and a
    ret

; B = the room's statues -> wMemPicks: each statue a different live entry whose
; monster has left the player (none left: $FF), picked at random (RNG16 mod the
; ones left).
MemRoll:
    ld a, b
    cp MEM_STATUES + 1
    jr c, .nOk
    ld a, MEM_STATUES
.nOk:
    ld [wMemTmp], a                 ; statues
    ld hl, wMemPicks
    ld c, MEM_STATUES
    ld a, $ff
.clr:
    ld [hl+], a
    dec c
    jr nz, .clr
    ld hl, wMemGone
    ld c, 16
    xor a
.zero:
    ld [hl+], a
    dec c
    jr nz, .zero
    ld c, 0
.live:
    ld a, [wMemCount]
    cp c
    jr z, .roster
    ld a, c
    call MemBitSet
    inc c
    jr .live
.roster:
    ld c, 0
.slot:
    ld a, c
    ld hl, $cac1
    call GetMonsterDataPtr
    call MemRecTag
    jr nc, .slotNext
    push bc
    call MemPresent
    pop bc
.slotNext:
    inc c
    ld a, c
    cp 40
    jr nz, .slot
    ld a, [$ca41]
    bit 7, a
    jr z, .count
    ld a, $02
    ld [$4100], a
    ld a, [$a000]
    cp $50
    jr nz, .poolEnd
    ld a, [$a001]
    cp $31
    jr nz, .poolEnd
    ld hl, $a010
    ld c, 40
.pool:
    ld a, $02
    ld [$4100], a
    call MemRecTag
    jr nc, .poolNext
    push hl
    push bc
    xor a
    ld [$4100], a
    call MemPresent
    pop bc
    pop hl
.poolNext:
    ld de, $95
    add hl, de
    dec c
    jr nz, .pool
.poolEnd:
    xor a
    ld [$4100], a
.count:
    ld c, 0
    ld e, 0
.cnt:
    ld a, [wMemCount]
    cp c
    jr z, .cntDone
    ld a, c
    push de
    call MemBitTest
    pop de
    jr z, .cntNext
    inc e
.cntNext:
    inc c
    jr .cnt
.cntDone:
    ld a, e
    ld [wMemTmp + 1], a             ; departed entries left to pick
    ld c, 0
.statue:
    ld a, [wMemTmp]
    cp c
    ret z
    ld a, [wMemTmp + 1]
    or a
    ret z
    push bc
    call GenerateRNG
    ld a, [wRNG1]
    ld l, a
    ld a, [wRNG2]
    ld h, a
    ld a, [wMemTmp + 1]
    call Div16x8To16                ; A = RNG16 mod the ones left
    ld e, a
    ld c, 0
.find:
    ld a, c
    push de
    call MemBitTest
    pop de
    jr z, .findNext
    ld a, e
    or a
    jr z, .found
    dec e
.findNext:
    inc c
    jr .find
.found:
    ld a, c
    call MemBitClr
    ld a, c
    call MemRing
    pop bc
    ld e, a
    ld a, c
    ld hl, wMemPicks
    add l
    ld l, a
    jr nc, .put
    inc h
.put:
    ld [hl], e
    ld hl, wMemTmp + 1
    dec [hl]
    inc c
    jr .statue

; D = tag, E = species of a monster the player still has -> its entry is not gone.
MemPresent:
    call MemFind
    ret nc
    jp MemBitClr

; A = live index -> HL = its byte in wMemGone, B = its bit.
MemBitAddr:
    ld b, a
    srl a
    srl a
    srl a
    ld hl, wMemGone
    add l
    ld l, a
    jr nc, .h
    inc h
.h:
    ld a, b
    and $07
    ld b, $01
    ret z
.s:
    sla b
    dec a
    jr nz, .s
    ret

MemBitSet:
    call MemBitAddr
    ld a, [hl]
    or b
    ld [hl], a
    ret

MemBitClr:
    call MemBitAddr
    ld a, b
    cpl
    and [hl]
    ld [hl], a
    ret

; -> nz = live entry A has left the player.
MemBitTest:
    call MemBitAddr
    ld a, [hl]
    and b
    ret

; Entry 9. Bank $77 StoryCommand kind 7 memorial [statue] (E = the statue): the
; statue's monster into the text inserts — $C180 {fallen} its nickname, $C190
; {fallen_level} its level, $C1A0 {fallen_species} its species' name — and $D8E1 =
; 1; no monster on it: $D8E1 = 0 (the script then says the empty words).
MemSay:
    xor a
    ld [$d8e1], a
    ld a, e
    cp MEM_STATUES
    ret nc
    ld hl, wMemPicks
    add l
    ld l, a
    jr nc, .p
    inc h
.p:
    ld a, [hl]
    cp $ff
    ret z
    call MemRingAddr
    call MemBank3
    ld de, wMemCur
    ld b, 7
.copy:
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, .copy
    call MemBank0
    ld hl, wMemCur + 3
    ld de, $c180
    ld b, 4
.nick:
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, .nick
    ld a, $f0
    ld [de], a
    ld de, $c190
    ld a, [wMemCur + 2]
    ld b, 0
.tens:
    cp 10
    jr c, .ones
    sub 10
    inc b
    jr .tens
.ones:
    ld c, a
    ld a, b
    or a
    jr z, .one
    ld [de], a                      ; the digit glyphs are $00-$09
    inc de
.one:
    ld a, c
    ld [de], a
    inc de
    ld a, $f0
    ld [de], a
    ld a, [wMemCur + 1]
    ld l, a
    ld h, $05                       ; text mode 5: a species' name
    ld de, $c1a0
    call SetupVRAMParams            ; ROM0: copies the text to DE ($F0 ends)
    ld a, $01
    ld [$d8e1], a
    ret

; =============================================================================
; S158 — BREEDING HINTS: MONUMENTS AND ARCHIVES (editor2/core/hints.py;
; PROJECT_COMPILER §2.66, DATA_STRUCTURES "Breeding hints (S158)", ROADMAP E15).
; A HINT is one row of the special breeding table (the effective table bank $69
; scans — a cross "pedigree x mate (+ min plus) -> child"), picked into the
; project's hint pool. Hint k = bit k of two bitsets in SRAM bank 3:
;   HINT_SRAM_UNLOCK + k / 8 — UNLOCKED: a monument showed it, or it was bred
;   HINT_SRAM_BRED   + k / 8 — BRED: an egg was made by exactly this cross
;   mask $80 >> (k & 7) (the event flags' order). Magic "H1" at bank 3 $A007; no
;   magic = nothing known yet: both bitsets are zeroed and the magic written at the
;   first access (HintEnsure) — bank $73 CF3NewGameClear does the same at a new game.
;   Written AT ONCE (not at the save): what the player has read stays known after a
;   reset (the user's call, S158).
; MONUMENTS (story command 8 sub 0, D = the monument): a pick among the hints NOT
;   unlocked whose child's family is in the monument's families (and, with "skip
;   owned", whose child the player has never owned — the library bit $CA94) —
;   random ((x >> 5) * n >> 11, x = the 16-bit RNG after a step: the LCG's high
;   bits), unlocked at once, remembered for this VISIT in its room slot
;   (wHintLatch): reading it again shows the same hint; the next visit (another
;   place / gate / floor — HintRoomNote, every room load) picks again. None left:
;   $D8E1 = 0 (the script says the "worn away" words).
; ARCHIVES (sub 2 start / sub 3 next, D = the family): the family's unlocked hints
;   in the compiler's order (HintFamLists), one per call, the BRED mark with each.
; The inserts (HintFill): $C180 {parent1} / $C190 {parent2} = a species' name or the
;   family's words ("any Dragon"), $C1A0 {child} = the child's name (+ " +N" when the
;   cross needs a plus), $C1B0 {bred} = the bred / not-bred words.
; Generated (hints.py data_lines): HINT_COUNT, HintTable (8 B a hint: dw the
;   special row's number ($FFFF = a hole: a pinned number whose cross is gone),
;   db pedigree matcher, mate matcher, child, min plus, the child's family 0-10
;   ($FF = a hole), 0), HintRiddles (dw a riddle text in this bank, 0 = none),
;   HINT_MON_COUNT + HintMonTable (3 B a monument: the room slot, the families
;   bits 0-7 / bits 8-10 + bit 7 = skip owned), HintFamLists (11 x dw -> dw n,
;   n x dw hint), HintFamWords (11 x dw -> a $F0-ended string), HintBredWord /
;   HintUnbredWord, the riddles.
; =============================================================================
HINT_SRAM_UNLOCK EQU $b000          ; SRAM bank 3: 256 B = hints 0-2047
HINT_SRAM_BRED EQU $b100            ; SRAM bank 3: 256 B
HINT_MAGIC EQU $a007                ; SRAM bank 3: "H1"
HINT_SLOTS EQU 8                    ; monuments a room can have (wHintLatch)

; Entry 10. Bank $77 StoryCommand kind 8 [sub, arg]: E = sub, D = arg.
;   0 pick [monument]  1 prepare [riddle?]  2 archive start [family]
;   3 archive next [family]. Answers in $D8E1 (see each). Clobbers all.
HintCommand:
    ld a, e
    or a
    jr z, HintPick
    dec a
    jp z, HintPrepare
    dec a
    jp z, HintArchiveStart
    dec a
    jp z, HintArchiveNext
    ret

; Sub 0 — a monument's hint (D = the monument): $D8E1 = 1 + the inserts filled
; (wHintCur = the hint), or 0 when none is left for it.
HintPick:
    xor a
    ld [$d8e1], a
    ld a, d
    cp HINT_MON_COUNT
    ret nc
    ld l, d
    ld h, $00
    ld c, l
    ld b, h
    add hl, hl
    add hl, bc
    ld bc, HintMonTable
    add hl, bc
    ld a, [hl+]
    ld [wHintTmp], a                ; the room slot
    ld a, [hl+]
    ld [wHintTmp + 1], a            ; families 0-7
    ld a, [hl]
    ld [wHintTmp + 2], a            ; families 8-10, bit 7 = skip owned
    call HintRoomNote               ; (a load the hook missed: still a new visit)
    call HintLatchAddr              ; HL = this slot's latch
    ld a, [hl+]
    ld e, a
    ld d, [hl]
    ld a, d
    or e
    jr z, .new
    dec de                          ; this visit's hint again
    jp HintShow
.new:
    call HintEnsure
    call MemBank3
    ld hl, $0000
    ld a, l
    ld [wHintN], a
    ld [wHintN + 1], a
.count:
    call HintEndOfTable
    jr z, .counted
    call HintCandidate
    jr nc, .cNext
    push hl
    ld hl, wHintN
    inc [hl]
    jr nz, .cInc
    inc hl
    inc [hl]
.cInc:
    pop hl
.cNext:
    inc hl
    jr .count
.counted:
    call MemBank0
    ld a, [wHintN]
    ld e, a
    ld a, [wHintN + 1]
    ld d, a
    or e
    ret z                           ; none left: $D8E1 = 0
    call GenerateRNG
    ld a, [wRNG1]
    ld b, a
    ld a, [wRNG2]
    ld c, a                         ; BC = the 16-bit RNG
    call HintMulPick                ; HL = (BC >> 5) * DE >> 11 < DE
    ld e, l
    ld d, h                         ; DE = which candidate (0-based)
    call MemBank3
    ld hl, $0000
.find:
    call HintCandidate
    jr nc, .fNext
    ld a, d
    or e
    jr z, .found
    dec de
.fNext:
    inc hl
    jr .find
.found:
    ld e, l
    ld d, h                         ; DE = the hint
    push de
    ld bc, HINT_SRAM_UNLOCK
    call HintBitAddr
    ld a, [hl]
    or b
    ld [hl], a                      ; unlocked — at once
    call MemBank0
    pop de
    call HintLatchAddr
    push de
    inc de
    ld a, e
    ld [hl+], a
    ld a, d
    ld [hl], a                      ; the latch = the hint + 1
    pop de
    ; fall through
; DE = a hint -> wHintCur, the inserts, $D8E1 = 1.
HintShow:
    ld a, e
    ld [wHintCur], a
    ld a, d
    ld [wHintCur + 1], a
    call HintFill
    ld a, $01
    ld [$d8e1], a
    ret

; Sub 1 — before a hint's words (D = 1: its riddle is next): the inserts filled
; again from wHintCur; D = 1 and the hint has a riddle -> wHintSay = 1 (the next
; shown text is the riddle — HintSay) and $D8E1 = 1; D = 1 and no riddle: $D8E1 = 0
; (a "both" monument then skips the riddle's turn); D = 0: $D8E1 = 1.
HintPrepare:
    push de
    ld a, [wHintCur]
    ld e, a
    ld a, [wHintCur + 1]
    ld d, a
    call HintFill
    pop de
    ld a, $01
    ld [$d8e1], a
    ld a, d
    or a
    ret z
    ld a, [wHintCur]
    ld e, a
    ld a, [wHintCur + 1]
    ld d, a
    call HintRiddleOf
    ld a, h
    or l
    jr z, .none
    ld a, $01
    ld [wHintSay], a
    ret
.none:
    xor a
    ld [$d8e1], a
    ret

; Sub 2 — an archive opened (D = the family): $D8E1 = 1 when the family has an
; unlocked hint, else 0; the list starts again (wHintCursor = 0).
HintArchiveStart:
    xor a
    ld [wHintCursor], a
    ld [wHintCursor + 1], a
    ld [$d8e1], a
    call HintFamList                ; HL = the list's first hint word, BC = n
    ret c
    ld de, $0000
    call HintNextUnlocked           ; carry = one found
    ret nc
    ld a, $01
    ld [$d8e1], a
    ret

; Sub 3 — the archive's next entry (D = the family): $D8E1 = 0 none left, else the
; inserts filled (wHintCur) and $D8E1 = 1 (more follow) / 2 (the last one).
HintArchiveNext:
    xor a
    ld [$d8e1], a
    call HintFamList
    ret c
    ld a, [wHintCursor]
    ld e, a
    ld a, [wHintCursor + 1]
    ld d, a
    call HintNextUnlocked           ; DE = its position, wHintK = the hint
    ret nc
    inc de
    ld a, e
    ld [wHintCursor], a
    ld a, d
    ld [wHintCursor + 1], a
    push hl
    push bc
    ld a, [wHintK]
    ld e, a
    ld a, [wHintK + 1]
    ld d, a
    call HintShow                   ; $D8E1 = 1
    pop bc
    pop hl
    ld a, [wHintCursor]
    ld e, a
    ld a, [wHintCursor + 1]
    ld d, a
    call HintNextUnlocked
    ret c                           ; more follow: 1
    ld a, $02
    ld [$d8e1], a
    ret

; D = a family -> HL = HintFamLists[D]'s first hint word, BC = its length; carry =
; no such family. Keeps D.
HintFamList:
    ld a, d
    cp 11
    ccf
    ret c
    ld l, d
    ld h, $00
    add hl, hl
    ld bc, HintFamLists
    add hl, bc
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    ld a, [hl+]
    ld c, a
    ld a, [hl+]
    ld b, a
    and a
    ret

; HL = the list's first hint word, BC = n, DE = a position -> carry + DE = the
; first position >= DE whose hint is unlocked (wHintK = that hint); no carry: none.
; Keeps HL / BC.
HintNextUnlocked:
    push hl
    push bc
    call HintEnsure
    pop bc
    pop hl
.loop:
    ld a, e
    cp c
    ld a, d
    sbc b
    jr nc, .none                    ; DE >= n
    push hl
    push de
    push bc
    add hl, de
    add hl, de
    ld a, [hl+]
    ld e, a
    ld d, [hl]                      ; DE = the hint
    ld a, e
    ld [wHintK], a
    ld a, d
    ld [wHintK + 1], a
    call MemBank3
    ld bc, HINT_SRAM_UNLOCK
    call HintBitAddr
    ld a, [hl]
    and b
    call MemBank0
    pop bc
    pop de
    pop hl
    jr nz, .found
    inc de
    jr .loop
.found:
    scf
    ret
.none:
    and a
    ret

; HL = a hint -> carry when it is a candidate of the current monument (wHintTmp
; +1 / +2): a real hint of one of its families, not unlocked, and (skip owned) a
; child the player has never owned. RAMB = 3 (the caller's window). Keeps HL / DE.
HintCandidate:
    push hl
    push de
    push hl
    call HintRowAddr                ; HL = its row
    ld de, 4
    add hl, de
    ld a, [hl+]
    ld [wHintTmp + 3], a            ; the child
    inc hl                          ; (+5 the min plus)
    ld a, [hl]                      ; +6 its family
    cp 11
    jr nc, .no2                     ; a hole ($FF)
    ld e, a
    ld a, [wHintTmp + 1]
    ld d, a
    ld a, e
    cp 8
    jr c, .lo
    sub 8
    ld e, a
    ld a, [wHintTmp + 2]
    and $07
    ld d, a
.lo:
    ld a, e
    inc a
    ld b, a
    ld a, d
.sh:
    rrca
    dec b
    jr nz, .sh                      ; carry = bit e of the families
    jr nc, .no2
    pop de                          ; DE = the hint
    push de
    ld bc, HINT_SRAM_UNLOCK
    call HintBitAddr
    ld a, [hl]
    and b
    jr nz, .no2                     ; unlocked already
    ld a, [wHintTmp + 2]
    bit 7, a
    jr z, .yes
    ld a, [wHintTmp + 3]            ; skip owned: the library bit $CA94
    ld e, a
    ld d, $00
    ld bc, $ca94
    call HintBitAddr
    ld a, [hl]
    and b
    jr nz, .no2
.yes:
    pop hl
    pop de
    pop hl
    scf
    ret
.no2:
    pop hl
    pop de
    pop hl
    and a
    ret

; HL = a hint -> Z when HL = HINT_COUNT (past the last). Keeps HL / DE / BC.
HintEndOfTable:
    ld a, l
    cp LOW(HINT_COUNT)
    ret nz
    ld a, h
    cp HIGH(HINT_COUNT)
    ret

; HL = a hint -> HL = its HintTable row (8 B). Keeps DE.
HintRowAddr:
    add hl, hl
    add hl, hl
    add hl, hl
    push de
    ld de, HintTable
    add hl, de
    pop de
    ret

; DE = a hint, BC = a bitset (or $CA94 with DE = a species) -> HL = its byte,
; B = its mask $80 >> (k & 7). Keeps DE.
HintBitAddr:
    ld l, e
    ld h, d
    srl h
    rr l
    srl h
    rr l
    srl h
    rr l
    add hl, bc
    ld a, e
    and $07
    ld b, $80
    ret z
.s:
    srl b
    dec a
    jr nz, .s
    ret

; -> HL = the current monument slot's latch (wHintLatch + 2 x slot). Keeps DE.
HintLatchAddr:
    ld a, [wHintTmp]
    and HINT_SLOTS - 1
    add a
    ld hl, wHintLatch
    add l
    ld l, a
    ret nc
    inc h
    ret

; The visit: (wMapRegion, wMapID, wGateID, wCurrentFloor) unlike the last room
; load's -> a new visit: the latches cleared. Clobbers A / HL.
HintRoomNote:
    ld hl, wHintPlace
    ld a, [wMapRegion]
    cp [hl]
    jr nz, .new
    inc hl
    ld a, [wMapID]
    cp [hl]
    jr nz, .new
    inc hl
    ld a, [wGateID]
    cp [hl]
    jr nz, .new
    inc hl
    ld a, [wCurrentFloor]
    cp [hl]
    ret z
.new:
    ld hl, wHintPlace
    ld a, [wMapRegion]
    ld [hl+], a
    ld a, [wMapID]
    ld [hl+], a
    ld a, [wGateID]
    ld [hl+], a
    ld a, [wCurrentFloor]
    ld [hl+], a
    ld b, 2 * HINT_SLOTS            ; wHintLatch follows wHintPlace
    xor a
.clr:
    ld [hl+], a
    dec b
    jr nz, .clr
    ret

; The magic "H1" in bank 3, else both bitsets zeroed + the magic. Clobbers A / BC /
; HL; leaves RAMB = 0.
HintEnsure:
    call MemBank3
    ld hl, HINT_MAGIC
    ld a, [hl+]
    cp $48
    jr nz, .init
    ld a, [hl]
    cp $31
    jr z, .ok
.init:
    ld hl, HINT_SRAM_UNLOCK
    ld bc, $0200
.clr:
    xor a
    ld [hl+], a
    dec bc
    ld a, b
    or c
    jr nz, .clr
    ld hl, HINT_MAGIC
    ld a, $48
    ld [hl+], a
    ld [hl], $31
.ok:
    jp MemBank0

; BC = x (16-bit), DE = n -> HL = (x >> 5) * n >> 11, which is < n (n <= 2048).
HintMulPick:
    ld a, 11
    ld [wHintTmp + 3], a
    xor a
    ld h, a
    ld l, a                         ; A:HL = the product
.mul:
    add hl, hl
    rla
    sla c
    rl b                            ; carry = x's next top bit
    jr nc, .skip
    add hl, de
    adc $00
.skip:
    push af
    ld a, [wHintTmp + 3]
    dec a
    ld [wHintTmp + 3], a
    jr z, .done
    pop af
    jr .mul
.done:
    pop af                          ; A:H:L = (x >> 5) * n (22 bits)
    ld l, h
    ld h, a
    srl h
    rr l
    srl h
    rr l
    srl h
    rr l                            ; >> 11
    ret

; DE = a hint -> HL = its riddle (0 = none). Keeps DE.
HintRiddleOf:
    ld l, e
    ld h, d
    add hl, hl
    push de
    ld de, HintRiddles
    add hl, de
    pop de
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    ret

; DE = a hint -> the inserts: $C180 {parent1}, $C190 {parent2}, $C1A0 {child} (+ " +N"),
; $C1B0 {bred}. Clobbers all.
HintFill:
    push de
    ld l, e
    ld h, d
    call HintRowAddr
    inc hl
    inc hl
    ld a, [hl+]
    push hl
    ld de, $c180
    call HintName
    pop hl
    ld a, [hl+]
    push hl
    ld de, $c190
    call HintName
    pop hl
    ld a, [hl+]
    ld b, [hl]                      ; the min plus
    push bc
    ld l, a
    ld h, $05                       ; text mode 5: a species' name
    ld de, $c1a0
    call SetupVRAMParams
    pop bc
    ld a, b
    or a
    jr z, .bred
    ld hl, $c1a0
.end:
    ld a, [hl+]
    cp $f0
    jr nz, .end
    dec hl
    ld [hl], $62                    ; " "
    inc hl
    ld [hl], $a2                    ; "+"
    inc hl
    ld a, b
    ld c, 0
.tens:
    cp 10
    jr c, .ones
    sub 10
    inc c
    jr .tens
.ones:
    ld b, a
    ld a, c
    or a
    jr z, .one
    ld [hl+], a                     ; the digit glyphs are $00-$09
.one:
    ld a, b
    ld [hl+], a
    ld [hl], $f0
.bred:
    pop de
    call HintEnsure
    call MemBank3
    ld bc, HINT_SRAM_BRED
    call HintBitAddr
    ld a, [hl]
    and b
    call MemBank0
    ld hl, HintUnbredWord
    jr z, .word
    ld hl, HintBredWord
.word:
    ld de, $c1b0
    ; fall through
; HL = a $F0-ended string -> DE (with the $F0).
HintCopy:
    ld a, [hl+]
    ld [de], a
    inc de
    cp $f0
    jr nz, HintCopy
    ret

; A = a matcher (a species, or a family code $F0-$FA), DE = an insert slot -> its
; name / the family's words.
HintName:
    cp $f0
    jr nc, .family
    ld l, a
    ld h, $05
    jp SetupVRAMParams
.family:
    sub $f0
    cp 11
    jr c, .ok
    xor a
.ok:
    ld l, a
    ld h, $00
    add hl, hl
    ld bc, HintFamWords
    add hl, bc
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    jr HintCopy

; Entry 11. Bank $16 HintBreed16 (region hint_breed_16: BreedCreateOffspring's `call
; BreedResolveOffspring` -> `call HintBreed16`, which resolves then far-calls here):
; the egg was made by special row wHintRow (bank $69 RelocatedSpecialScan; $FFFF =
; none) -> the hint of that row, if the pool has it, is UNLOCKED and BRED. Clobbers all.
HintBreed:
    ld a, [wHintRow]
    ld c, a
    ld a, [wHintRow + 1]
    ld b, a
    and c
    inc a
    ret z                           ; no special row made it
    ld hl, $0000
.find:
    call HintEndOfTable
    ret z                           ; not a hint
    push hl
    call HintRowAddr
    ld a, [hl+]
    cp c
    jr nz, .next
    ld a, [hl]
    cp b
    jr z, .hit
.next:
    pop hl
    inc hl
    jr .find
.hit:
    pop de                          ; DE = the hint
    call HintEnsure
    call MemBank3
    push de
    ld bc, HINT_SRAM_UNLOCK
    call HintBitAddr
    ld a, [hl]
    or b
    ld [hl], a
    pop de
    ld bc, HINT_SRAM_BRED
    call HintBitAddr
    ld a, [hl]
    or b
    ld [hl], a
    jp MemBank0

; Entry 12. Bank $60 TextOverride, a SHOWN text while wHintSay = 1 (set by sub 1 right
; before the riddle's words): that text becomes the current hint's riddle (in this
; bank) — DE / [$C824] / wTextOvrPtr as an edited text (bank $77 OneOnlySay's way).
HintSay:
    xor a
    ld [wHintSay], a
    push de                         ; (the text's table, kept when there is no riddle)
    ld a, [wHintCur]
    ld e, a
    ld a, [wHintCur + 1]
    ld d, a
    push de
    call HintRiddleOf
    pop de
    ld a, h
    or l
    jr z, .keep                     ; (no riddle: the words as written)
    pop de
    ld a, l
    ld [wTextOvrPtr], a
    ld a, h
    ld [wTextOvrPtr + 1], a
    ld a, $79
    ld [$c824], a                   ; the engine reads the riddle from this bank
    ld a, [$c823]
    ld l, a
    ld h, $00
    add hl, hl                      ; 2 * id
    ld a, LOW(wTextOvrPtr)
    sub l
    ld e, a
    ld a, HIGH(wTextOvrPtr)
    sbc h
    ld d, a                         ; DE = wTextOvrPtr - 2 * id
    ret
.keep:
    pop de
    ret
